#!/usr/bin/env python3
"""s35p02 「비율이 바뀌는 세 갈래」 — 자연선택 · 유전적 부동 · 유전자 흐름.

s35p01 의 연못 문법을 그대로 이어받는다 — 연못=집단, 구슬 두 색=대립유전자.
셋 다 위 웅덩이는 검·흰 반반으로 같고, 아래 웅덩이만 달라진다.
「그 사이에 무엇이 있었나」가 곧 세 힘이다.

  왼쪽   통로를 막고 똑바로 선 체 — 흰 구슬만 걸려 쌓이고 아래엔 검은 것뿐  → 자연선택(방향이 있다)
  가운데 아무도 없고 통로만 극단적으로 잘록 — 아래는 거의 다 흰 구슬        → 부동·병목(우연이다)
  가운데 아래 국자로 몇 개만 떠서 옮긴 작은 웅덩이 — 검은 구슬뿐            → 부동·창시자
  오른쪽 판을 활짝 올린 수문 — 구슬이 양쪽으로 오가고 두 웅덩이가 닮았다      → 유전자 흐름(차이를 줄인다)

기출 근거
  #1097(2010) 창시자 효과 — 「소수 개체가 격리되어 원집단을 반영하지 않는 새 유전자 풀」
  #1098(2012) 유전적 부동의 원인 = 병목효과 + 창시자효과 (오답 선지는 전부 자연선택의 유형)
  → 그래서 병목과 창시자를 **같은 가운데 칸**에 두고 체(선택)와 갈라 놓았다.
"""
import os, re, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SK = os.path.join(ROOT, 'sketchy.html')

BR = ('세 갈래 모두 <b>위 웅덩이는 반반으로 같다</b>. 아래가 달라지는 것은 그 사이에 무엇이 있었느냐 '
      '때문이다 — <b>체가 있으면 방향</b>, <b>목이 좁으면 우연</b>, <b>수문이 열려 있으면 섞임</b>이다.')

BX = """<p><b>셋 다 같은 데서 출발한다.</b> 위 웅덩이는 세 갈래 모두 검·흰 반반이다. 아래가 달라지는 것은 오직 그 사이에 놓인 것 때문이고, 그 셋이 미시진화를 일으키는 <b>자연선택 · 유전적 부동 · 유전자 흐름</b>이다.</p><p><b>체만이 방향을 가진다.</b> 왼쪽에서 체는 <b>흰 구슬만</b> 걸러낸다. 누가 봐도 한쪽으로 간다. 그래서 셋 중 <b>적응을 일관되게 일으키는 것은 자연선택뿐</b>이다 — 이것이 이 단원에서 가장 자주 확인되는 한 줄이다. 다만 자연선택도 <b>우연과 선별의 결합</b>이다. 변이를 만드는 것은 돌연변이(우연)이고, 선택은 그중 유리한 것을 고를 뿐이다(선별). 그리고 선택이 직접 잡는 것은 유전자형이 아니라 <b>표현형</b> — 체에 걸리는 것은 겉모습이다.</p><p><b>가운데에는 아무도 없다.</b> 그런데도 아래 웅덩이는 거의 흰 구슬뿐이다. 통로의 목이 좁아 <b>몇 개만 지나갔고</b>, 그 몇 개가 우연히 치우쳤을 뿐이다. 이것이 <b>유전적 부동</b>이고 좁은 목이 <b>병목 효과</b>다. <b>집단이 작을수록 효과가 크다</b> — 표본이 작으면 우연이 크게 튀기 때문이다. 부동은 빈도를 무작위로 출렁이게 하고, 유전적 변이를 잃게 하며, 중립이거나 약간 해로운 대립유전자조차 우연히 <b>고정(100%)</b>시킬 수 있다.</p><p><b>국자도 같은 힘이다.</b> 몇 개만 떠서 따로 떨어진 웅덩이에 부으면 그 작은 표본이 원래 연못과 다르다 — <b>창시자 효과</b>다. 기출은 이 둘을 묶어서 낸다. 「유전적 부동의 원인으로 바른 것은?」의 답이 <b>병목효과·창시자효과</b>이고, 오답 선지에는 방향성·분단성·안정화·자웅도태 같은 <b>자연선택의 유형</b>이 깔린다. 체 쪽과 목·국자 쪽을 갈라 두는 것이 전부다.</p><p><b>수문은 섞는다.</b> 오른쪽은 판이 활짝 올라가 구슬이 양쪽으로 오간다. 그 결과 두 웅덩이의 색 구성이 <b>서로 같아졌다</b> — 유전자 흐름은 흔히 <b>집단 간 차이를 줄인다</b>. 부동이 <b>집단 안</b>에서 변이를 잃는 것과 방향이 다르다는 점을 이 대비로 잡아 둔다. 흐름이 늘 나쁜 것도 아니다. 모기의 살충제 내성 대립유전자가 한 곳에서 생겨 전 세계로 퍼진 것처럼 <b>적응을 퍼뜨리기도</b> 하고, 반대로 본토에서 계속 흘러드는 대립유전자가 섬 집단의 완전한 국지 적응을 막기도 한다(레이크이리 물뱀).</p><div class='qx'><div class='qh'>여기서 갈리는 문제</div><p class='qlead'>이 자리의 문항은 <b>이름을 어느 통에 넣느냐</b>로만 갈린다. <b>병목·창시자는 둘 다 부동</b>이고, <b>방향성·분단성·안정화·자웅도태는 전부 자연선택의 유형</b>이다. 선지에 이 둘이 섞여 나오면 그 경계 하나로 답이 정해진다. 그림에서 <b>체가 있는 칸</b>과 <b>아무도 없는 칸</b>을 갈라 둔 것이 그 경계다.</p><details class='qitem'><summary><span class='qsrc'>BM하 #1098 · 2012</span><span class='qq'>다음 중 유전적 부동의 원인으로 바르게 제시된 것은?</span></summary><ol class='qc'><li>자연선택, 인위선택</li><li>자연선택, 교배</li><li class='ans'>병목효과, 창시자효과</li><li>방향성선택, 분단성 선택</li><li>안정화 선택, 자웅도태</li></ol><div class='qa'><b>정답 ③</b> — 부동은 <b>우연</b>에 의한 빈도 변화이고, 그 대표 사례가 <b>병목효과</b>와 <b>창시자효과</b>다. 그림에서 이 둘이 <b>가운데 칸 하나에</b> 함께 놓인 이유가 이것이다 — 좁은 목을 지난 것도, 국자로 뜬 것도, 고른 사람이 아무도 없다.<br><b>①·②</b>는 자연선택·인위선택·교배를 든다. 셋 다 <b>고르는 힘</b>이라 우연이 아니다. 그림의 왼쪽 칸, 체를 붙들고 선 사람이 그쪽이다.<br><b>④ 방향성·분단성 선택 · ⑤ 안정화 선택·자웅도태</b>는 전부 <b>자연선택의 유형</b> 이름이다. 부동과는 통이 다르다. 이 문항의 오답 넷 중 셋이 여기에 몰려 있다는 것이 요점이다 — <b>「선택」이라는 글자가 보이면 부동이 아니다.</b></div></details><details class='qitem'><summary><span class='qsrc'>BM하 #1097 · 2010</span><span class='qq'>얼마 안 되는 수의 개체들이 큰 집단으로부터 격리될 때, 이 작은 무리가 유전자풀이 원래 집단을 반영하지 않는 새 집단을 이루는 현상은?</span></summary><ol class='qc'><li>유전자흐름(gene flow)</li><li class='ans'>창시자효과(founder effect)</li><li>돌연변이(mutation)</li><li>지리적 변이(geographic variation)</li><li>유전적 다형성(genetic polymorphism)</li></ol><div class='qa'><b>정답 ②</b> — 발문의 세 조각이 그대로 그림이다. 「<b>얼마 안 되는 수</b>」가 국자 한 술, 「<b>격리</b>」가 따로 떨어진 웅덩이, 「<b>원래 집단을 반영하지 않는</b>」이 그 웅덩이만 검은 구슬뿐인 것이다.<br><b>① 유전자흐름</b>이 이 문항의 진짜 함정이다. 둘 다 「개체가 옮겨 간다」로 들리기 때문이다. 그러나 흐름은 <b>두 집단 사이를 오가며 차이를 줄이는</b> 힘이고(그림 오른쪽, 열린 수문), 창시자는 <b>떨어져 나가 새 집단을 만드는</b> 일이다. <b>오가느냐 떨어지느냐</b>로 가른다.<br><b>③ 돌연변이</b>는 새 대립유전자를 만드는 일이라 「원래 집단에 없던 것이 생긴다」이고, 창시자는 <b>있던 것 중 일부만 가져간다</b>이다. 국자에는 새 색이 없다.<br><b>④ 지리적 변이</b>는 원인이 아니라 결과의 서술이고, <b>⑤ 유전적 다형성</b>은 집단에 여러 대립유전자가 공존하는 상태를 가리키는 말이라 「현상의 이름」을 묻는 이 발문에 맞지 않는다.</div></details><div class='qrule'>고르는 것이 있으면 <b>선택</b>, 아무도 없는데 비율이 변했으면 <b>부동</b>(병목·창시자), 두 집단을 오가면 <b>흐름</b>이다. <b>선택만 방향을 만들고</b>, 부동은 변이를 잃게 하며, 흐름은 차이를 줄인다.</div></div>"""

ROWS = [
    ('세 갈래 모두 위 웅덩이는 검은 구슬과 흰 구슬이 반반이다',
     '셋 다 <b>같은 데서 출발한다</b>. 아래가 달라지는 것은 그 사이에 무엇이 있었느냐 때문이고, '
     '그 셋이 미시진화의 세 메커니즘 — <b>자연선택 · 유전적 부동 · 유전자 흐름</b>이다',
     ['J1-3']),
    ('왼쪽 — 통로를 가로막고 똑바로 선 체 · 흰 구슬만 위쪽에 걸려 쌓였다',
     '<b>자연선택</b>. 체가 <b>한 색만</b> 골라낸다 — 셋 중 유일하게 <b>방향</b>이 있다. '
     '체에 걸리는 것은 겉모습이라 선택은 유전자형이 아니라 <b>표현형에 직접 작용</b>한다',
     ['J1-17', 'J1-15']),
    ('그래서 왼쪽 아래 웅덩이에는 검은 구슬만 남았다',
     '<b>적응을 일관되게 일으키는 것은 자연선택뿐</b>이다. 나머지 둘은 방향이 없다. '
     '여기서 「기여도」로 재는 것이 <b>상대적응도</b> — 다음 세대 유전자 풀에 얼마나 남기느냐다',
     ['J1-4', 'J1-16']),
    ('가운데 — 아무도 없고 통로만 극단적으로 잘록하다',
     '<b>유전적 부동</b>. 고른 사람이 없는데 비율이 변한다 — 좁은 목을 <b>몇 개만</b> 지났기 때문이다. '
     '이것이 <b>병목 효과</b>다',
     ['J1-20']),
    ('그 아래 웅덩이는 거의 다 흰 구슬이다',
     '우연만으로 이렇게 된다. <b>집단이 작을수록 효과가 크다</b> — 표본이 작으면 우연이 크게 튄다. '
     '부동은 빈도를 무작위로 출렁이게 하고, 변이를 잃게 하며, 중립이거나 약간 해로운 것조차 '
     '우연히 <b>고정(100%)</b>시킬 수 있다',
     ['J1-18', 'J1-19', 'J1-19#1', 'J1-19#2', 'J1-19#3']),
    ('그 아래 — 국자로 몇 개만 떠서 따로 떨어진 작은 웅덩이에 붓는 사람 · 그 웅덩이는 검은 구슬뿐',
     '<b>창시자 효과</b>. 소수가 새 자리에 정착하면 그 작은 표본이 원집단을 반영하지 않는다. '
     '<b>병목과 창시자는 둘 다 유전적 부동</b>이고, 기출은 이 둘을 묶어 낸다',
     ['J1-21']),
    ('오른쪽 — 판을 활짝 올린 수문 · 구슬이 양쪽으로 오간다',
     '<b>유전자 흐름</b> — 집단 사이 대립유전자 이동. 창시자와 헷갈리는 자리인데, '
     '흐름은 <b>오가는</b> 것이고 창시자는 <b>떨어져 나가는</b> 것이다',
     ['J1-22']),
    ('그래서 오른쪽 두 웅덩이는 색 구성이 서로 같아졌다',
     '유전자 흐름은 흔히 <b>집단 간 차이를 줄인다</b>. 부동이 <b>집단 안</b>에서 변이를 잃는 것과 '
     '방향이 다르다. 흐름은 적응을 퍼뜨리기도 하고(모기의 살충제 내성) 국지 적응을 막기도 한다(레이크이리 물뱀)',
     ['J1-25', 'J1-25#1', 'J1-25#2', 'J1-23', 'J1-24']),
]


def close_brace(t, i):
    op = t[i]
    cl = {'{': '}', '[': ']'}[op]
    d, q, j = 0, None, i
    while j < len(t):
        c = t[j]
        if q:
            if c == '\\':
                j += 2
                continue
            if c == q:
                q = None
        elif c in '"\'`':
            q = c
        elif c == op:
            d += 1
        elif c == cl:
            d -= 1
            if d == 0:
                return j
        j += 1
    raise SystemExit('괄호 안 닫힘')


def q2(s):
    assert '"' not in s and '\\' not in s, s
    return '"%s"' % s


def main():
    src = open(SK, encoding='utf-8').read()
    assert "{id:'s35p02'" not in src, '이미 있다'
    assert '`' not in BX and "'" not in BR

    i = src.index("{id:'s35p01'")
    e = close_brace(src, i)

    rows = []
    for prop, fact, cards in ROWS:
        r = '[' + q2(prop) + ',' + q2(fact)
        if cards:
            r += ',[' + ','.join(q2(c) for c in cards) + ']'
        rows.append(r + ']')

    panel = ("{id:'s35p02',t:'비율이 바뀌는 세 갈래',br:'" + BR + "',bx:`" + BX
             + "`,f:[" + ',\n  '.join(rows) + ']}')
    out = src[:e + 1] + ',\n ' + panel + src[e + 1:]

    k = out.index("{id:'s35p02'")
    blk = out[k:close_brace(out, k) + 1]
    ids = re.findall(r"\{id:'([sd]\d+p\d+[ab]?)'", out)
    assert len(ids) == len(set(ids)), '패널 id 중복'
    assert ids.index('s35p02') == ids.index('s35p01') + 1, '위치 오류'
    cards = re.findall(r'"(J1-[\w#]+)"', blk)
    assert len(cards) == len(set(cards)), '카드 중복'
    print('패널 %d개 · s35p02 행 %d · 카드 %d장' % (len(ids), len(ROWS), len(cards)))
    open(SK, 'w', encoding='utf-8').write(out)
    return 0


if __name__ == '__main__':
    sys.exit(main())
